package szserver.world;

import com.google.gson.*;
import szserver.persistence.*;
import szserver.util.Json;
import java.io.*;
import java.util.*;
import static szserver.persistence.CheckpointDataRows.*;

/** Typed map-state codec. The canonical source journal and native terrain are not rewritten.
 * Capture at a command barrier on the world owner, then stream on that worker while simulation
 * continues. Reader creates a separate World and never touches the source or a running world. */
public final class WorldMapCheckpoint {
    public static final List<String> SECTIONS=WorldCheckpointStore.SECTIONS.subList(0,6);
    private WorldMapCheckpoint(){}
    public static final class Export {
        private final World.MapCheckpointView state;private final String identity,registry,nativeBase;
        private Export(World world){state=world.mapCheckpointView();identity=world.identity();registry=world.sceneRegistryDigest();nativeBase=world.checkpointTerrain() instanceof RegionTerrain regions?regions.liveCommits().generation():"";}
        private Export(Export source){var s=source.state;state=new World.MapCheckpointView(s.overlays().detached(),Map.copyOf(s.anchors()),Map.copyOf(s.physical()),Set.copyOf(s.edited()),Map.copyOf(s.metadata()),Set.copyOf(s.metadataIds()),Set.copyOf(s.removed()),Set.copyOf(s.metadataLive()),Map.copyOf(s.ranks()),s.nextRank(),s.epoch());identity=source.identity;registry=source.registry;nativeBase=source.nativeBase;}
        /** Freeze on the command worker, before releasing its mutation barrier. No disk IO. */
        public Export detached(){SceneCollision.worker();return new Export(this);}
        public void write(WorldCheckpointStore.Sink sink)throws Exception{
            write(sink,null,false);
        }
        public void writeBound(WorldCheckpointStore.Sink sink,String binding)throws Exception{write(sink,binding,true);}
        private void write(WorldCheckpointStore.Sink sink,String binding,boolean boundRow)throws Exception{
            var overlays=state.overlays();long cells=0,tiles=0,scenes=0;for(var chunk:overlays.checkpointChunks()){cells+=chunk.cells().size();tiles+=chunk.tiles().size();scenes+=chunk.scenes().size();}
            sink.begin("world_control");JsonObject control=row("control");control.addProperty("version",2);control.addProperty("identity",identity);control.addProperty("registry",registry);control.addProperty("epoch",state.epoch());control.addProperty("nextRank",state.nextRank());control.addProperty("chunks",overlays.checkpointChunkCount());control.addProperty("blocks",cells);control.addProperty("tiles",tiles);control.addProperty("tilePayloads",overlays.tilePayloadCount());control.addProperty("scenes",scenes);control.addProperty("anchors",state.anchors().size());control.addProperty("physical",state.physical().size());control.addProperty("edited",state.edited().size());control.addProperty("metadata",state.metadata().size());control.addProperty("metadataIds",state.metadataIds().size());control.addProperty("removed",state.removed().size());control.addProperty("metadataLive",state.metadataLive().size());control.addProperty("ranks",state.ranks().size());CheckpointDataRows.write(sink,control);
            if(boundRow){JsonObject base=row("base_binding");base.add("value",binding==null?JsonNull.INSTANCE:new JsonPrimitive(binding));CheckpointDataRows.write(sink,base);}
            if(!nativeBase.isEmpty()){if(!boundRow)throw new IllegalArgumentException("checkpoint_native_base_requires_binding");CheckpointDataRows.write(sink,Json.tree(Map.of("kind","native_base","generation",nativeBase,"sceneBase",true)));}
            for(var chunk:overlays.checkpointChunks()){JsonObject value=row("chunk");value.addProperty("x",(int)(chunk.key()>>32));value.addProperty("z",(int)chunk.key());value.addProperty("revision",chunk.revision());CheckpointDataRows.write(sink,value);}sink.end();
            sink.begin("block_overlays");for(var chunk:overlays.checkpointChunks()){
                if(chunk.cells().size()>128){JsonObject value=row("block_chunk");value.addProperty("x",(int)(chunk.key()>>32));value.addProperty("z",(int)chunk.key());value.addProperty("format","SZVC1");value.addProperty("count",chunk.cells().size());value.add("data",binary(VoxelCheckpoint.encode(chunk.cells())));CheckpointDataRows.write(sink,value);}
                else for(var cell:chunk.cells().entrySet()){JsonObject value=cell("block",chunk.key(),cell.getKey());var voxel=cell.getValue();value.addProperty("id",voxel.id());value.addProperty("metadata",voxel.metadata());value.addProperty("revision",voxel.revision());CheckpointDataRows.write(sink,value);}
            }sink.end();
            sink.begin("tile_overlays");for(var chunk:overlays.checkpointChunks()){
                int clears=0;for(var cell:chunk.tiles().entrySet())if(cell.getValue()==null)clears++;boolean packed=clears>128;
                if(packed){JsonObject value=row("tile_clear_chunk");value.addProperty("x",(int)(chunk.key()>>32));value.addProperty("z",(int)chunk.key());value.addProperty("format","SZTC1");value.addProperty("count",clears);value.add("data",binary(TileClearCheckpoint.encode(chunk.tiles(),chunk.tileIds(),clears)));CheckpointDataRows.write(sink,value);}
                for(var cell:chunk.tiles().entrySet()){TilePayload.Tile tile=cell.getValue();if(packed&&tile==null)continue;JsonObject value=cell("tile",chunk.key(),cell.getKey());value.addProperty("id",chunk.tileIds().get(cell.getKey()));value.add("record",tile==null?JsonNull.INSTANCE:binary(tile.record()));value.add("complete",tile==null||tile.completeState()==null?JsonNull.INSTANCE:binary(tile.completeState()));CheckpointDataRows.write(sink,value);}
            }sink.end();
            sink.begin("scene_overlays");for(var chunk:overlays.checkpointChunks())for(var scene:chunk.scenes().entrySet())entry(sink,"scene",(int)(chunk.key()>>32),(int)chunk.key(),scene.getKey(),scene.getValue());sink.end();
            sink.begin("scene_anchors");for(var anchor:state.anchors().entrySet())entry(sink,"anchor",anchor.getValue().x(),anchor.getValue().z(),anchor.getKey(),anchor.getValue().entry());sink.end();
            sink.begin("portal_indexes");for(var p:state.physical().values())portal(sink,"physical",p);for(var p:state.metadata().values())portal(sink,"metadata",p);
            for(var set:Map.of("edited",state.edited(),"metadataIds",state.metadataIds(),"removed",state.removed(),"metadataLive",state.metadataLive()).entrySet())for(UUID id:set.getValue()){JsonObject value=row(set.getKey());value.addProperty("id",id.toString());CheckpointDataRows.write(sink,value);}
            for(var rank:state.ranks().entrySet()){JsonObject value=row("rank");value.addProperty("id",rank.getKey().toString());value.addProperty("value",rank.getValue().value());value.addProperty("created",rank.getValue().created());CheckpointDataRows.write(sink,value);}sink.end();
        }
    }
    /** Caller holds the serialized command barrier; invoke this constant-work capture on WorldLoop. */
    public static Export capture(World world){return new Export(world);}
    private static JsonObject row(String kind){JsonObject row=new JsonObject();row.addProperty("kind",kind);return row;}
    private static JsonObject cell(String kind,long key,int cell){JsonObject row=row(kind);row.addProperty("x",(int)(key>>32));row.addProperty("z",(int)key);row.addProperty("cell",cell);return row;}
    private static void entry(WorldCheckpointStore.Sink sink,String kind,int x,int z,UUID id,ScenePayload.Entry entry)throws Exception{
        JsonObject value=row(kind);value.addProperty("x",x);value.addProperty("z",z);value.addProperty("id",id.toString());value.addProperty("bodies",entry==null?0:entry.occurrences().size());CheckpointDataRows.write(sink,value);
        if(entry!=null)for(var occurrence:entry.occurrences()){JsonObject body=row("body");body.addProperty("container",occurrence.container());body.addProperty("asset",occurrence.object().asset());body.add("record",binary(occurrence.object().record()));CheckpointDataRows.write(sink,body);}
    }
    private static void vec(DataOutputStream out,World.Vec p)throws IOException{out.writeDouble(p.x());out.writeDouble(p.y());out.writeDouble(p.z());}
    private static World.Vec vec(DataInputStream in)throws IOException{return new World.Vec(in.readDouble(),in.readDouble(),in.readDouble());}
    private static void portal(WorldCheckpointStore.Sink sink,String kind,NativePortal p)throws Exception{
        var bytes=new ByteArrayOutputStream();try(var out=new DataOutputStream(bytes)){out.writeLong(p.id().getMostSignificantBits());out.writeLong(p.id().getLeastSignificantBits());out.writeUTF(p.asset());out.writeUTF(p.behaviour());vec(out,p.position());out.writeDouble(p.scale());var s=p.parameters();out.writeBoolean(s.interaction());out.writeDouble(s.size());out.writeBoolean(s.horizontalOffset());out.writeBoolean(s.verticalOffset());out.writeDouble(s.cooldown());out.writeInt(s.destinations().size());for(var d:s.destinations()){out.writeBoolean(d.coordinates()!=null);if(d.coordinates()!=null)vec(out,d.coordinates());out.writeDouble(d.weight());out.writeUTF(d.location());}}
        JsonObject value=row(kind);value.add("record",binary(bytes.toByteArray()));CheckpointDataRows.write(sink,value);
    }
    static World.Block block(long key,int cell){long x=((long)(int)(key>>32))*16+(cell&15),z=((long)(int)key)*16+((cell>>4)&15);if(x<-szserver.world.MapBounds.HORIZONTAL||x>szserver.world.MapBounds.HORIZONTAL||z<-szserver.world.MapBounds.HORIZONTAL||z>szserver.world.MapBounds.HORIZONTAL)throw new IllegalArgumentException("checkpoint_block_bounds");return new World.Block((int)x,cell>>8,(int)z);}
    private static long chunk(JsonObject row){int x=(int)integer(row,"x",Integer.MIN_VALUE,Integer.MAX_VALUE),z=(int)integer(row,"z",Integer.MIN_VALUE,Integer.MAX_VALUE);return BlockOverlays.key(x,z);}
    private static NativePortal portal(JsonObject row)throws Exception{
        fields(row,"kind","record");byte[] bytes=binary(row.get("record"),MAX_BYTES);try(var in=new DataInputStream(new ByteArrayInputStream(bytes))){UUID id=new UUID(in.readLong(),in.readLong());String asset=in.readUTF(),behaviour=in.readUTF();World.Vec position=vec(in);double scale=in.readDouble();boolean interaction=in.readBoolean();double size=in.readDouble();boolean horizontal=in.readBoolean(),vertical=in.readBoolean();double cooldown=in.readDouble();int count=in.readInt();
            if(!NativePortal.behaviour(behaviour)||asset.isEmpty()||!finite(position)||!Double.isFinite(scale)||scale<=0||!Double.isFinite(size)||size<0||!Double.isFinite(cooldown)||cooldown<0||count<0||count>in.available()/11)throw new IllegalArgumentException("checkpoint_portal");
            List<NativePortal.Destination> destinations=new ArrayList<>(count);for(int n=0;n<count;n++){World.Vec coordinates=in.readBoolean()?vec(in):null;double weight=in.readDouble();String location=in.readUTF();if(!Double.isFinite(weight)||weight<0)throw new IllegalArgumentException("checkpoint_portal_weight");destinations.add(new NativePortal.Destination(coordinates,weight,location));}if(in.available()!=0)throw new IllegalArgumentException("checkpoint_portal_trailing");return new NativePortal(id,asset,behaviour,position,scale,new NativePortal.Parameters(interaction,size,horizontal,vertical,cooldown,destinations));
        }
    }
    private static boolean finite(World.Vec p){return Double.isFinite(p.x())&&Double.isFinite(p.y())&&Double.isFinite(p.z());}
    public static final class Reader {
        private String binding,nativeBase="";private boolean boundRow,nativeRow,nativeSceneBase;
        public boolean nativeSceneBase(){return nativeSceneBase;}
        public String nativeBase(){return nativeBase;}
        public String binding(){return binding;}
        private final World source;private final BlockOverlays overlays;private final Map<UUID,World.SceneLocation> anchors=new HashMap<>();
        private final Map<UUID,NativePortal> physical=new HashMap<>(),metadata=new HashMap<>();private final Set<UUID> edited=new HashSet<>(),metadataIds=new HashSet<>(),removed=new HashSet<>(),metadataLive=new HashSet<>();private final Map<UUID,World.PortalRank> ranks=new HashMap<>();
        private JsonObject control;private int version;private int sectionAt=-1;private long blocks,tiles,scenes;private boolean finished;private String entrySection;private long entryChunk;private UUID entryId;private int bodies;private List<ScenePayload.Occurrence> occurrences;private long occurrenceBytes;
        public Reader(World source){this.source=Objects.requireNonNull(source);overlays=new BlockOverlays(source.mapLimits());}
        private int countLimit(String field){return switch(field){case "blocks"->source.mapLimits().voxels();case "chunks"->source.mapLimits().chunks();case "tiles"->version==2?source.mapLimits().tileStates():100000;case "scenes","anchors"->100000;default->400000;};}
        /** Logical rows after CheckpointDataRows.Reader; returns false for command-side sections. */
        public boolean accept(String section,JsonObject row)throws Exception{
            if(finished)throw new IllegalArgumentException("checkpoint_map_finished");int next=SECTIONS.indexOf(section);if(next<0){if(occurrences!=null)throw new IllegalArgumentException("checkpoint_scene_incomplete");return false;}if(next<sectionAt)throw new IllegalArgumentException("checkpoint_map_section_order");if(occurrences!=null){body(section,row);return true;}sectionAt=next;String kind=Json.text(row,"kind",32);
            switch(section){
                case "world_control"->{if(kind.equals("control")){if(control!=null)throw new IllegalArgumentException("checkpoint_map_duplicate_control");version=(int)integer(row,"version",1,2);if(version==2){fields(row,"kind","version","identity","registry","epoch","nextRank","chunks","blocks","tiles","tilePayloads","scenes","anchors","physical","edited","metadata","metadataIds","removed","metadataLive","ranks");integer(row,"tilePayloads",0,100000);}else fields(row,"kind","version","identity","registry","epoch","nextRank","chunks","blocks","tiles","scenes","anchors","physical","edited","metadata","metadataIds","removed","metadataLive","ranks");if(!Json.text(row,"identity",4096).equals(source.identity())||!row.get("registry").isJsonPrimitive()||!row.get("registry").getAsJsonPrimitive().isString()||!row.get("registry").getAsString().equals(source.sceneRegistryDigest()))throw new IllegalArgumentException("checkpoint_map_binding");integer(row,"epoch",0,Long.MAX_VALUE);integer(row,"nextRank",SceneCatalog.MAX_IDENTITIES,Long.MAX_VALUE);for(String key:List.of("chunks","blocks","tiles","scenes","anchors","physical","edited","metadata","metadataIds","removed","metadataLive","ranks"))integer(row,key,0,countLimit(key));control=row.deepCopy();}
                    else if(kind.equals("base_binding")){required();fields(row,"kind","value");if(boundRow||overlays.checkpointChunkCount()!=0)throw new IllegalArgumentException("checkpoint_base_binding_order");boundRow=true;var value=row.get("value");if(!value.isJsonNull()){if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isString()||!value.getAsString().matches("[0-9a-f]{64}"))throw new IllegalArgumentException("checkpoint_base_binding");binding=value.getAsString();}}
                    else if(kind.equals("native_base")){required();if(row.has("sceneBase")){fields(row,"kind","generation","sceneBase");nativeSceneBase=flag(row,"sceneBase");}else fields(row,"kind","generation");if(nativeRow||!boundRow||overlays.checkpointChunkCount()!=0)throw new IllegalArgumentException("checkpoint_native_base_order");nativeRow=true;nativeBase=Json.text(row,"generation",36);if(!UUID.fromString(nativeBase).toString().equals(nativeBase))throw new IllegalArgumentException("checkpoint_native_base_generation");}
                    else if(kind.equals("chunk")){required();fields(row,"kind","x","z","revision");if(overlays.checkpointChunkCount()>=integer(control,"chunks",0,countLimit("chunks")))throw new IllegalArgumentException("checkpoint_map_chunk_count");overlays.restoreChunk(chunk(row),integer(row,"revision",1,Long.MAX_VALUE));}else throw new IllegalArgumentException("checkpoint_map_kind");}
                case "block_overlays"->{required();if(kind.equals("block_chunk")){
                    fields(row,"kind","x","z","format","count","data");if(!Json.text(row,"format",16).equals("SZVC1"))throw new IllegalArgumentException("checkpoint_voxel_chunk_format");int count=(int)integer(row,"count",1,65536);long key=chunk(row);if(blocks+count>source.mapLimits().voxels())throw new IllegalArgumentException("checkpoint_block_limit");
                    VoxelCheckpoint.read(binary(row.get("data"),VoxelCheckpoint.MAX_BYTES),count,(cell,value)->{block(key,cell);overlays.restoreVoxel(key,cell,value);});blocks+=count;
                }else{if(!kind.equals("block"))throw new IllegalArgumentException("checkpoint_map_kind");fields(row,"kind","x","z","cell","id","metadata","revision");int cell=(int)integer(row,"cell",0,65535);long key=chunk(row);block(key,cell);if(++blocks>source.mapLimits().voxels())throw new IllegalArgumentException("checkpoint_block_limit");overlays.restoreVoxel(key,cell,new BlockOverlays.Voxel((int)integer(row,"id",0,4095),(int)integer(row,"metadata",0,15),integer(row,"revision",1,Long.MAX_VALUE)));}}
                case "tile_overlays"->{required();if(kind.equals("tile_clear_chunk")){if(version!=2)throw new IllegalArgumentException("checkpoint_tile_clear_version");fields(row,"kind","x","z","format","count","data");if(!Json.text(row,"format",16).equals("SZTC1"))throw new IllegalArgumentException("checkpoint_tile_clear_format");int count=(int)integer(row,"count",1,65536);long key=chunk(row);if(tiles+count>countLimit("tiles"))throw new IllegalArgumentException("checkpoint_tile_clear_limit");TileClearCheckpoint.read(binary(row.get("data"),TileClearCheckpoint.MAX_BYTES),count,(cell,id)->{block(key,cell);overlays.restoreTile(key,cell,null,id);});tiles+=count;
                }else{if(!kind.equals("tile"))throw new IllegalArgumentException("checkpoint_map_kind");fields(row,"kind","x","z","cell","id","record","complete");int cell=(int)integer(row,"cell",0,65535),id=(int)integer(row,"id",0,4095);long key=chunk(row);World.Block position=block(key,cell);TilePayload.Tile tile=null;if(!row.get("record").isJsonNull()){tile=TilePayload.single(binary(row.get("record"),68));if(tile.x()!=position.x()||tile.y()!=position.y()||tile.z()!=position.z()||id==0)throw new IllegalArgumentException("checkpoint_tile_position");if(!row.get("complete").isJsonNull()){byte[] complete=binary(row.get("complete"),szserver.client.CompleteTileState.MAX_STATE);TilePayload.Tile decoded=szserver.client.CompleteTileState.decode(complete);if(!Arrays.equals(tile.record(),decoded.record()))throw new IllegalArgumentException("checkpoint_tile_appearance_state");tile=tile.withCompleteState(complete);}}else if(!row.get("complete").isJsonNull())throw new IllegalArgumentException("checkpoint_tile_null_state");if(tiles>=countLimit("tiles"))throw new IllegalArgumentException("checkpoint_tile_clear_limit");overlays.restoreTile(key,cell,tile,id);tiles++;}}
                case "scene_overlays","scene_anchors"->{required();if(!kind.equals(section.equals("scene_overlays")?"scene":"anchor"))throw new IllegalArgumentException("checkpoint_map_kind");fields(row,"kind","x","z","id","bodies");entryChunk=chunk(row);entryId=uuid(row,"id");bodies=(int)integer(row,"bodies",0,ScenePayload.MAX_OBJECTS);entrySection=section;occurrences=new ArrayList<>(Math.min(bodies,16));occurrenceBytes=0;if(bodies==0)installEntry(null);}
                case "portal_indexes"->{required();switch(kind){case "physical","metadata"->{NativePortal p=portal(row);var target=kind.equals("physical")?physical:metadata;if(target.size()>=400000||target.putIfAbsent(p.id(),p)!=null)throw new IllegalArgumentException("checkpoint_portal_duplicate_or_limit");}case "edited","metadataIds","removed","metadataLive"->{fields(row,"kind","id");Set<UUID> target=switch(kind){case "edited"->edited;case "metadataIds"->metadataIds;case "removed"->removed;default->metadataLive;};if(target.size()>=400000||!target.add(uuid(row,"id")))throw new IllegalArgumentException("checkpoint_portal_duplicate_or_limit");}case "rank"->{fields(row,"kind","id","value","created");UUID id=uuid(row,"id");long value=integer(row,"value",SceneCatalog.MAX_IDENTITIES,integer(control,"nextRank",SceneCatalog.MAX_IDENTITIES,Long.MAX_VALUE)-1);if(ranks.size()>=400000||ranks.putIfAbsent(id,new World.PortalRank(value,flag(row,"created")))!=null)throw new IllegalArgumentException("checkpoint_portal_duplicate_or_limit");}default->throw new IllegalArgumentException("checkpoint_map_kind");}}
                default->throw new IllegalArgumentException("checkpoint_map_section");
            }return true;
        }
        private void required(){if(control==null)throw new IllegalArgumentException("checkpoint_map_control_required");}
        public void validateNativeBase(NativeCommitIndex index){
            for(var chunk:overlays.checkpointChunks()){long base=index.revision((int)(chunk.key()>>32),(int)chunk.key());if(chunk.revision()<base||chunk.cells().isEmpty()&&chunk.tiles().isEmpty()&&chunk.scenes().isEmpty()&&(base==0||base!=chunk.revision()))throw new IllegalArgumentException("checkpoint_native_revision_mismatch");}
            for(long key:index.revisions().keySet())if(overlays.version((int)(key>>32),(int)key)<index.revision((int)(key>>32),(int)key))throw new IllegalArgumentException("checkpoint_native_counter_missing");
        }
        private void body(String section,JsonObject row){if(!section.equals(entrySection)||!Json.text(row,"kind",32).equals("body"))throw new IllegalArgumentException("checkpoint_scene_incomplete");fields(row,"kind","container","asset","record");SceneObject object=new SceneObject(Json.text(row,"asset",4096),binary(row.get("record"),ScenePayload.MAX_OBJECT));if(!entryId.equals(object.identity()))throw new IllegalArgumentException("checkpoint_scene_identity");occurrenceBytes+=object.recordSize();if(occurrenceBytes>ScenePayload.MAX_RAW+(long)ScenePayload.MAX_RECORD)throw new IllegalArgumentException("checkpoint_scene_body_bytes");boolean container=flag(row,"container");if(!container&&!occurrences.isEmpty()&&occurrences.get(occurrences.size()-1).container())throw new IllegalArgumentException("checkpoint_scene_channel_order");occurrences.add(new ScenePayload.Occurrence(container,object));if(occurrences.size()==bodies)installEntry(ScenePayload.Entry.of(occurrences));}
        private void installEntry(ScenePayload.Entry entry){if(entrySection.equals("scene_overlays")){overlays.restoreScene(entryChunk,entryId,entry);scenes++;}else{if(anchors.size()>=100000||anchors.putIfAbsent(entryId,new World.SceneLocation((int)(entryChunk>>32),(int)entryChunk,entry))!=null)throw new IllegalArgumentException("checkpoint_anchor_duplicate_or_limit");}occurrences=null;}
        public World finish(){required();if(finished||occurrences!=null)throw new IllegalArgumentException("checkpoint_map_incomplete");
            Map<String,Long> counts=Map.ofEntries(Map.entry("chunks",(long)overlays.checkpointChunkCount()),Map.entry("blocks",blocks),Map.entry("tiles",tiles),Map.entry("scenes",scenes),Map.entry("anchors",(long)anchors.size()),Map.entry("physical",(long)physical.size()),Map.entry("edited",(long)edited.size()),Map.entry("metadata",(long)metadata.size()),Map.entry("metadataIds",(long)metadataIds.size()),Map.entry("removed",(long)removed.size()),Map.entry("metadataLive",(long)metadataLive.size()),Map.entry("ranks",(long)ranks.size()));
            for(var count:counts.entrySet())if(count.getValue()!=integer(control,count.getKey(),0,countLimit(count.getKey())))throw new IllegalArgumentException("checkpoint_map_count:"+count.getKey());
            if(version==2&&overlays.tilePayloadCount()!=integer(control,"tilePayloads",0,100000))throw new IllegalArgumentException("checkpoint_map_tile_payload_count");
            if(!metadataIds.containsAll(metadata.keySet())||!metadataLive.containsAll(metadata.keySet())||!metadataIds.containsAll(metadataLive)||!edited.containsAll(metadataIds)||!edited.containsAll(physical.keySet())||!nativeSceneBase&&(!edited.containsAll(removed)||!edited.containsAll(ranks.keySet()))||!ranks.keySet().containsAll(metadata.keySet()))throw new IllegalArgumentException("checkpoint_portal_index_state");Set<Long> order=new HashSet<>();for(var rank:ranks.values())if(!order.add(rank.value()))throw new IllegalArgumentException("checkpoint_portal_rank_duplicate");
            for(var chunk:overlays.checkpointChunks())if(nativeBase.isEmpty()&&chunk.cells().isEmpty()&&chunk.tiles().isEmpty()&&chunk.scenes().isEmpty())throw new IllegalArgumentException("checkpoint_empty_chunk");
            World fresh=source.restoredMapCheckpoint(new World.MapCheckpointView(overlays,anchors,physical,edited,metadata,metadataIds,removed,metadataLive,ranks,integer(control,"nextRank",SceneCatalog.MAX_IDENTITIES,Long.MAX_VALUE),integer(control,"epoch",0,Long.MAX_VALUE)));finished=true;return fresh;
        }
    }
}
